function show_page
  $tab_play := 0
  $tab_sound := 0
  $tab_perf := 0
  if ($page = 0)
    $tab_play := 1
  end if
  if ($page = 1)
    $tab_sound := 1
  end if
  if ($page = 2)
    $tab_perf := 1
  end if
  $ui_i := 0
  while ($ui_i < $NUM_UI)
    if (%ui_page[$ui_i] = -1 or %ui_page[$ui_i] = $page)
      set_control_par(%ui_id[$ui_i], $CONTROL_PAR_HIDE, $HIDE_PART_NOTHING)
    else
      set_control_par(%ui_id[$ui_i], $CONTROL_PAR_HIDE, $HIDE_WHOLE_CONTROL)
    end if
    inc($ui_i)
  end while
end function

function play_voice
  $pv_id := play_note($pv_note, 127, $pv_off, 0)
  set_event_par_arr($pv_id, $EVENT_PAR_ALLOW_GROUP, 0, $ALL_GROUPS)
  set_event_par_arr($pv_id, $EVENT_PAR_ALLOW_GROUP, 1, $pv_grp)
  change_vol($pv_id, $pv_vol, 0)
  change_tune($pv_id, $pv_tune + $bend, 0)
  if ($pv_pan # 0)
    change_pan($pv_id, $pv_pan, 0)
  end if
  if ($pv_fade > 0)
    fade_in($pv_id, $pv_fade)
  end if
  if ($nv_n < 32)
    %nv_id[$nv_n] := $pv_id
    %nv_r[$nv_n] := $pv_role
    %nv_b[$nv_n] := $pv_vol
    inc($nv_n)
  end if
end function

function reg_new
  $rn_i := 0
  while ($rn_i < $nv_n)
    if (%src_n[$rs_src] < $MAXV)
      $rn_j := $rs_src * $MAXV + %src_n[$rs_src]
      %src_v[$rn_j] := %nv_id[$rn_i]
      %src_r[$rn_j] := %nv_r[$rn_i]
      %src_b[$rn_j] := %nv_b[$rn_i]
      %src_n[$rs_src] := %src_n[$rs_src] + 1
    else
      fade_out(%nv_id[$rn_i], 30000, 1)
    end if
    inc($rn_i)
  end while
end function

function release_src
  $rl_i := 0
  while ($rl_i < %src_n[$rs_src])
    fade_out(%src_v[$rs_src * $MAXV + $rl_i], $rs_time, 1)
    inc($rl_i)
  end while
  %src_n[$rs_src] := 0
  %src_sus[$rs_src] := 0
end function

function pend_new
  $pn_i := 0
  while ($pn_i < $nv_n)
    if ($pq_n < 512)
      %pq_id[$pq_n] := %nv_id[$pn_i]
      %pq_t[$pq_n] := $pq_rel
      inc($pq_n)
    else
      fade_out(%nv_id[$pn_i], 20000, 1)
    end if
    inc($pn_i)
  end while
end function

function process_pending
  $pp_i := 0
  while ($pp_i < $pq_n)
    if (%pq_t[$pp_i] <= $tick)
      fade_out(%pq_id[$pp_i], $rel_us, 1)
      dec($pq_n)
      %pq_id[$pp_i] := %pq_id[$pq_n]
      %pq_t[$pp_i] := %pq_t[$pq_n]
    else
      inc($pp_i)
    end if
  end while
end function

function release_all
  $ra_s := 0
  while ($ra_s < 129)
    if (%src_n[$ra_s] > 0)
      $rs_src := $ra_s
      call release_src
    end if
    %src_sus[$ra_s] := 0
    inc($ra_s)
  end while
  $ra_i := 0
  while ($ra_i < $pq_n)
    fade_out(%pq_id[$ra_i], $rs_time, 1)
    inc($ra_i)
  end while
  $pq_n := 0
end function

function pedal_up
  $pu_s := 0
  while ($pu_s < 128)
    if (%src_sus[$pu_s] = 1 and %src_held[$pu_s] = 0)
      $rs_src := $pu_s
      $rs_time := $rel_us
      call release_src
    end if
    inc($pu_s)
  end while
end function

function apply_cutoff
  $fx_v := $cut_base + $cut_mod + $cut_lfo
  if ($fx_v < 0)
    $fx_v := 0
  end if
  if ($fx_v > 1000000)
    $fx_v := 1000000
  end if
  set_engine_par($ENGINE_PAR_CUTOFF, $fx_v, -1, 0, $NI_INSERT_BUS)
end function

function scale_snap
  if ($scale_type > 0)
    $sc_pc := ($sc_note - $scale_key + 120) mod 12
    $sc_d := 0
    $sc_t := $sc_pc
    while (%scale_mask[$scale_type * 12 + $sc_t] = 0 and $sc_d < 11)
      inc($sc_d)
      $sc_t := ($sc_pc - $sc_d + 12) mod 12
    end while
    $sc_note := $sc_note - $sc_d
    if ($sc_note < 0)
      $sc_note := $sc_note + 12
    end if
  end if
end function

function build_chord
  $bc_n := 0
  %ch_note[$bc_src * 8] := $bc_root
  $bc_n := 1
  if ($chord = 15 or $chord = 16)
    $bc_need := 3
    if ($chord = 16)
      $bc_need := 4
    end if
    $sc_t := $scale_type
    if ($sc_t = 0)
      $sc_t := 1
    end if
    $bc_step := 0
    $bc_p := $bc_root
    while ($bc_n < $bc_need and $bc_p < $bc_root + 24)
      inc($bc_p)
      if (%scale_mask[$sc_t * 12 + (($bc_p - $scale_key + 120) mod 12)] = 1)
        inc($bc_step)
        if ($bc_step = 2 or $bc_step = 4 or $bc_step = 6)
          if ($bc_p <= 127)
            %ch_note[$bc_src * 8 + $bc_n] := $bc_p
            inc($bc_n)
          end if
        end if
      end if
    end while
  else
    $bc_i := 1
    while ($bc_i < %chord_n[$chord])
      $bc_p := $bc_root + %chord_iv[$chord * 6 + $bc_i]
      if ($bc_p <= 127)
        %ch_note[$bc_src * 8 + $bc_n] := $bc_p
        inc($bc_n)
      end if
      inc($bc_i)
    end while
  end if
  %ch_n[$bc_src] := $bc_n
end function

function arp_sort
  $as_i := 0
  while ($as_i < 64)
    if ($as_i < $arp_n)
      %arp_sorted[$as_i] := %arp_note[$as_i]
    else
      %arp_sorted[$as_i] := 1000
    end if
    inc($as_i)
  end while
  sort(%arp_sorted, 0)
end function

function start_note
  $nv_n := 0
  $sv_db := int(real($vsens) * 0.4 * 20000.0 * log10(real($sn_vel) / 127.0) / 20.0)
  $ly_a := %grp[%lay_grp[$layer_a]]
  $ly_b := -1
  if ($layer_b > 0)
    $ly_b := %grp[%lay_grp[$layer_b - 1]]
  end if
  $oct_n := 1
  %oct_iv[0] := 0
  select ($oct_mode)
    case 1
      %oct_iv[1] := 12
      $oct_n := 2
    case 2
      %oct_iv[1] := -12
      $oct_n := 2
    case 3
      %oct_iv[1] := 12
      %oct_iv[2] := -12
      $oct_n := 3
    case 4
      %oct_iv[1] := 7
      $oct_n := 2
    case 5
      %oct_iv[1] := 12
      %oct_iv[2] := 19
      $oct_n := 3
  end select
  $oi := 0
  while ($oi < $oct_n)
    $op := $sn_note + %oct_iv[$oi]
    if ($op >= 0 and $op <= 127)
      $pv_note := $op
      $pv_tune := 0
      $pv_off := $sn_off
      $pv_pan := 0
      $pv_role := 3
      $pv_fade := $att_us
      if ($sn_fade >= 0)
        $pv_fade := $sn_fade
      end if
      if ($ly_a # $NI_NOT_FOUND)
        $pv_grp := $ly_a
        $pv_vol := $sv_db
        if ($ly_b # -1)
          $pv_vol := $pv_vol + $ga_db
        end if
        if ($oi > 0)
          $pv_vol := $pv_vol + $oct_lvl * 100
        end if
        call play_voice
      end if
      if ($ly_b # -1 and $ly_b # $NI_NOT_FOUND)
        $pv_grp := $ly_b
        $pv_vol := $sv_db + $gb_db
        if ($oi > 0)
          $pv_vol := $pv_vol + $oct_lvl * 100
        end if
        call play_voice
      end if
    end if
    inc($oi)
  end while
end function

function arp_fire
  $af_total := $arp_n * $arp_oct
  if ($af_total > 0)
    $af_len := %rate_ticks[$arp_rate]
    $af_gate := ($af_len * $arp_gate) / 100
    if ($af_gate < 1)
      $af_gate := 1
    end if
    $af_vel := $arp_lastvel
    if (($tick mod 24) < $af_len)
      $af_vel := $af_vel + $arp_accent
    end if
    if ($af_vel > 127)
      $af_vel := 127
    end if
    if ($arp_mode = 6)
      $af_i := 0
      while ($af_i < $arp_n)
        $sn_note := %arp_note[$af_i]
        $sn_vel := $af_vel
        $sn_off := 0
        $sn_fade := -1
        call start_note
        $pq_rel := $tick + $af_gate
        call pend_new
        inc($af_i)
      end while
    else
      select ($arp_mode)
        case 1
          $af_idx := $arp_step mod $af_total
        case 2
          $af_idx := $af_total - 1 - ($arp_step mod $af_total)
        case 3
          if ($af_total = 1)
            $af_idx := 0
          else
            $af_per := 2 * $af_total - 2
            $af_idx := $arp_step mod $af_per
            if ($af_idx >= $af_total)
              $af_idx := $af_per - $af_idx
            end if
          end if
        case 4
          $af_idx := random(0, $af_total - 1)
        case 5
          $af_idx := $arp_step mod $af_total
      end select
      $af_e := $af_idx mod $arp_n
      $af_o := $af_idx / $arp_n
      if ($arp_mode = 5)
        $af_note := %arp_note[$af_e] + 12 * $af_o
      else
        $af_note := %arp_sorted[$af_e] + 12 * $af_o
      end if
      if ($af_note <= 127)
        $sn_note := $af_note
        $sn_vel := $af_vel
        $sn_off := 0
        $sn_fade := -1
        call start_note
        $pq_rel := $tick + $af_gate
        call pend_new
      end if
    end if
    inc($arp_step)
  end if
end function

function arp_add
  if ($arp_latch = 1 and $keys_down <= 1)
    $arp_n := 0
  end if
  $aa_was := $arp_n
  $aa_i := 0
  while ($aa_i < %ch_n[$aa_src])
    if ($arp_n < 64)
      %arp_note[$arp_n] := %ch_note[$aa_src * 8 + $aa_i]
      %arp_src[$arp_n] := $aa_src
      inc($arp_n)
    end if
    inc($aa_i)
  end while
  call arp_sort
  if ($aa_was = 0)
    $arp_step := 0
    call arp_fire
    $arp_next := $tick + %rate_ticks[$arp_rate]
  end if
end function

function arp_remove
  $ar_j := 0
  $ar_i := 0
  while ($ar_i < $arp_n)
    if (%arp_src[$ar_i] # $ar_src)
      %arp_note[$ar_j] := %arp_note[$ar_i]
      %arp_src[$ar_j] := %arp_src[$ar_i]
      inc($ar_j)
    end if
    inc($ar_i)
  end while
  $arp_n := $ar_j
  call arp_sort
end function

function calc_blend
  ~fr := real($blend) / 1000.0
  ~fg := cos(~fr * 1.5707963)
  if (~fg < 0.0001)
    ~fg := 0.0001
  end if
  $ga_db := int(20000.0 * log10(~fg))
  ~fg := sin(~fr * 1.5707963)
  if (~fg < 0.0001)
    ~fg := 0.0001
  end if
  $gb_db := int(20000.0 * log10(~fg))
end function

function mono_apply
  $mt_i := 0
  while ($mt_i < $mono_n)
    change_tune(%mono_v[$mt_i], $mono_tune + $bend, 0)
    inc($mt_i)
  end while
end function

function mono_start
  $ms_i := 0
  while ($ms_i < $mono_n)
    fade_out(%mono_v[$ms_i], 12000, 1)
    inc($ms_i)
  end while
  $sn_note := $sk_note
  $sn_vel := $mono_vel
  $sn_off := 0
  $sn_fade := -1
  call start_note
  $ms_i := 0
  while ($ms_i < $nv_n)
    %mono_v[$ms_i] := %nv_id[$ms_i]
    inc($ms_i)
  end while
  $mono_n := $nv_n
  $mono_base := $sk_note
  $mono_cur := $sk_note
  $mono_tune := 0
  inc($gl_token)
end function

function stack_remove
  $sk_j := 0
  $sk_i := 0
  while ($sk_i < $stk_n)
    if (%stk[$sk_i] # $sk_note)
      %stk[$sk_j] := %stk[$sk_i]
      inc($sk_j)
    end if
    inc($sk_i)
  end while
  $stk_n := $sk_j
end function

function stack_push
  call stack_remove
  if ($stk_n < 16)
    %stk[$stk_n] := $sk_note
    inc($stk_n)
  end if
end function

function color_keys
  $kc_i := 0
  while ($kc_i < 128)
    set_key_color($kc_i, $KEY_COLOR_INACTIVE)
    set_key_type($kc_i, $NI_KEY_TYPE_NONE)
    set_key_name($kc_i, "")
    inc($kc_i)
  end while
  $kc_i := 24
  while ($kc_i <= 96)
    set_key_color($kc_i, $KEY_COLOR_CYAN)
    set_key_type($kc_i, $NI_KEY_TYPE_DEFAULT)
    inc($kc_i)
  end while
end function

