      $blend := 200
      call upd_blend
      $attack := 1500
      call upd_attack
      $release := 250
      call upd_release
      $vsens := 10
      call upd_vsens
      $move_amt := 350
      call upd_move_amt
      $oct_mode := 0
      call upd_oct_mode
      $oct_lvl := -60
      call upd_oct_lvl
      $mono := 0
      call upd_mono
      $glide := 80
      call upd_glide
      $move_rate := 3
      call upd_move_rate
      $modwheel := 500
      call upd_modwheel
  end select
end function

