on note
  ignore_event($EVENT_ID)
  inc($keys_down)
  %src_held[$EVENT_NOTE] := 1
  if ($mono = 1)
    $mono_vel := $EVENT_VELOCITY
    $sk_note := $EVENT_NOTE
    call stack_push
    if ($mono_n > 0 and abs($EVENT_NOTE - $mono_base) <= 24)
      inc($gl_token)
      $p_tok := $gl_token
      $p_from := $mono_tune
      $p_to := ($EVENT_NOTE - $mono_base) * 100000
      $mono_cur := $EVENT_NOTE
      if ($glide = 0)
        $mono_tune := $p_to
        call mono_apply
      else
        $p_steps := $glide / 5
        if ($p_steps < 1)
          $p_steps := 1
        end if
        $p_s := 1
        while ($p_s <= $p_steps and $p_tok = $gl_token)
          $mono_tune := $p_from + (($p_to - $p_from) / $p_steps) * $p_s
          call mono_apply
          wait(5000)
          inc($p_s)
        end while
        if ($p_tok = $gl_token)
          $mono_tune := $p_to
          call mono_apply
        end if
      end if
    else
      $sk_note := $EVENT_NOTE
      call mono_start
    end if
    exit
  end if
  $p_vel := $EVENT_VELOCITY
  if ($hum_vel > 0)
    $p_vel := $p_vel + random(0 - $hum_vel, $hum_vel)
    if ($p_vel < 1)
      $p_vel := 1
    end if
    if ($p_vel > 127)
      $p_vel := 127
    end if
  end if
  $sc_note := $EVENT_NOTE
  call scale_snap
  $bc_root := $sc_note
  $bc_src := $EVENT_NOTE
  call build_chord
  if ($arp_mode > 0)
    $arp_lastvel := $p_vel
    $aa_src := $EVENT_NOTE
    call arp_add
    exit
  end if
  if (%src_n[$EVENT_NOTE] > 0)
    $rs_src := $EVENT_NOTE
    $rs_time := $retrig_us
    call release_src
  end if
  if ($hum_time > 0)
    wait(random(0, $hum_time * 1000) + 1)
  end if
  $p_i := 0
  $p_cnt := %ch_n[$EVENT_NOTE]
  while ($p_i < $p_cnt)
    if ($p_i > 0 and $strum > 0)
      wait($strum * 1000)
    end if
    if (%src_held[$EVENT_NOTE] = 1 or $pedal = 1)
      $sn_note := %ch_note[$EVENT_NOTE * 8 + $p_i]
      $sn_vel := $p_vel
      $sn_off := 0
      $sn_fade := -1
      call start_note
      $rs_src := $EVENT_NOTE
      call reg_new
    else
      $p_i := $p_cnt
    end if
    inc($p_i)
  end while
end on

on release
  dec($keys_down)
  if ($keys_down < 0)
    $keys_down := 0
  end if
  %src_held[$EVENT_NOTE] := 0
  if ($mono = 1)
    $sk_note := $EVENT_NOTE
    call stack_remove
    if ($EVENT_NOTE = $mono_cur)
      if ($stk_n > 0)
        $q_tgt := %stk[$stk_n - 1]
        if ($mono_n > 0 and abs($q_tgt - $mono_base) <= 24)
          inc($gl_token)
          $q_tok := $gl_token
          $q_from := $mono_tune
          $q_to := ($q_tgt - $mono_base) * 100000
          $mono_cur := $q_tgt
          if ($glide = 0)
            $mono_tune := $q_to
            call mono_apply
          else
            $q_steps := $glide / 5
            if ($q_steps < 1)
              $q_steps := 1
            end if
            $q_s := 1
            while ($q_s <= $q_steps and $q_tok = $gl_token)
              $mono_tune := $q_from + (($q_to - $q_from) / $q_steps) * $q_s
              call mono_apply
              wait(5000)
              inc($q_s)
            end while
            if ($q_tok = $gl_token)
              $mono_tune := $q_to
              call mono_apply
            end if
          end if
        else
          $sk_note := $q_tgt
          call mono_start
        end if
      else
        $mt_i := 0
        while ($mt_i < $mono_n)
          fade_out(%mono_v[$mt_i], $rel_us, 1)
          inc($mt_i)
        end while
        $mono_n := 0
        inc($gl_token)
      end if
    end if
    exit
  end if
  if ($arp_mode > 0)
    if ($arp_latch = 0)
      $ar_src := $EVENT_NOTE
      call arp_remove
    end if
    exit
  end if
  if ($pedal = 1)
    %src_sus[$EVENT_NOTE] := 1
  else
    $rs_src := $EVENT_NOTE
    $rs_time := $rel_us
    call release_src
  end if
end on

on controller
  if ($CC_NUM = 64 and $use_pedal = 1)
    if (%CC[64] >= 64)
      $pedal := 1
    else
      if ($pedal = 1)
        $pedal := 0
        call pedal_up
      end if
    end if
  end if
  if ($CC_NUM = 120 or $CC_NUM = 123)
    $rs_time := 20000
    call release_all
  end if
  if ($CC_NUM = $VCC_PITCH_BEND)
    $cb_v := (%CC[$VCC_PITCH_BEND] * $pb_range * 100) / 8191 * 1000
    change_tune($ALL_EVENTS, $cb_v - $bend, 1)
    $bend := $cb_v
  end if
  if ($CC_NUM = 1)
    $cut_mod := (%CC[1] * $modwheel * 1000) / 127
    call apply_cutoff
  end if
end on

on listener
  if ($NI_SIGNAL_TYPE = $NI_SIGNAL_TIMER_BEAT)
    inc($tick)
    if ($pq_n > 0)
      call process_pending
    end if
    if ($arp_mode > 0 and $arp_n > 0 and $tick >= $arp_next)
      call arp_fire
      $lt_len := %rate_ticks[$arp_rate]
      $lt_sw := ($lt_len * $arp_swing) / 6
      if (($arp_step mod 2) = 1)
        $arp_next := $tick + $lt_len + $lt_sw
      else
        $arp_next := $tick + $lt_len - $lt_sw
      end if
    end if
    if ($move_amt > 0)
      inc($lfo_pos)
      if ($lfo_pos >= %lfo_ticks[$move_rate])
        $lfo_pos := 0
      end if
      ~lfo_r := sin(6.2831853 * real($lfo_pos) / real(%lfo_ticks[$move_rate]))
      $cut_lfo := int(~lfo_r * real($move_amt) * 250.0)
      call apply_cutoff
    end if
  end if
end on

